Method: fr.baretto.ollamassist.chat.tools.BracketCallParser#parse
Signature: public Optional<DetectedToolCall> parse(String text)
Body: {
    if (text == null || text.isBlank()) {
        return Optional.empty();
    }
    Matcher matcher = BRACKET_PATTERN.matcher(text);
    if (!matcher.find()) {
        return Optional.empty();
    }
    String toolName = matcher.group(1);
    String argsText = matcher.group(2);
    // For CreateFile specifically, we expect 2 arguments: path and content
    if ("CreateFile".equals(toolName)) {
        Map<String, String> arguments = parseCreateFileArguments(argsText);
        if (!arguments.isEmpty()) {
            return Optional.of(DetectedToolCall.builder().toolName(toolName).arguments(arguments).originalText(matcher.group(0)).detectedBy(getParserName()).build());
        }
    }
    return Optional.empty();
}
