Method: fr.baretto.ollamassist.completion.EnhancedCompletionService#generateNewSuggestion
Doc: * Generates a new suggestion using the optimized model assistant.
Signature: private void generateNewSuggestion(@NotNull Editor editor, @NotNull CompletionContext context, @NotNull String cacheKey, @NotNull ProgressIndicator indicator)
Body: {
    log.debug("generateNewSuggestion() starting");
    indicator.setText("Generating AI suggestion...");
    log.debug("About to call OptimizedLightModelAssistant.completeAsync()");
    log.debug("Context: {}", context.getImmediateContext().substring(0, Math.min(50, context.getImmediateContext().length())));
    log.debug("File extension: {}", context.getFileExtension());
    CompletableFuture<String> completionFuture = OptimizedLightModelAssistant.completeAsync(context.getImmediateContext(), context.getFileExtension(), context.getProjectContext(), context.getSimilarPatterns());
    log.debug("CompletableFuture created for AI completion");
    completionFuture.thenAccept(rawSuggestion -> {
        log.debug("AI completion thenAccept() callback executing");
        if (indicator.isCanceled()) {
            log.info("🚫 Enhanced suggestion cancelled by user");
            return;
        }
        log.info("🤖 Enhanced raw suggestion received: '{}'", rawSuggestion != null ? rawSuggestion.substring(0, Math.min(100, rawSuggestion.length())) : "null");
        try {
            String processedSuggestion = processSuggestion(rawSuggestion, editor);
            log.info("✨ Processed suggestion: '{}'", processedSuggestion);
            if (processedSuggestion.trim().isEmpty()) {
                log.warn("Processed suggestion is empty, falling back to basic");
                generateBasicSuggestion(editor, indicator);
                return;
            }
            // Cache the result
            cache.put(cacheKey, processedSuggestion);
            ApplicationManager.getApplication().invokeLater(() -> {
                if (!indicator.isCanceled()) {
                    int caretOffset = ApplicationManager.getApplication().runReadAction((Computable<Integer>) () -> editor.getCaretModel().getOffset());
                    log.info("🎯 Showing enhanced suggestion at offset {} with content: '{}'", caretOffset, processedSuggestion);
                    suggestionManager.showSuggestion(editor, caretOffset, processedSuggestion);
                    attachActionHandler(editor);
                }
            });
        } catch (Exception e) {
            log.error("❌ Suggestion processing failed", e);
            generateBasicSuggestion(editor, indicator);
        }
    }).exceptionally(throwable -> {
        log.error("❌ Enhanced suggestion generation failed", throwable);
        generateBasicSuggestion(editor, indicator);
        return null;
    });
}
Method: fr.baretto.ollamassist.completion.LightModelService#handleSuggestion
Signature: public void handleSuggestion(Editor editor)
Body: {
    ApplicationManager.getApplication().invokeLater(() -> {
        // Show immediate loading feedback in the editor
        int caretOffset = editor.getCaretModel().getOffset();
        suggestionManager.showLoading(editor, caretOffset, "Generating suggestion");
        new Task.Backgroundable(editor.getProject(), "OllamAssist: Generating intelligent suggestion...", true) {

            @Override
            public void run(@NotNull ProgressIndicator indicator) {
                try {
                    // Use enhanced context if available, otherwise fallback to basic context
                    if (contextProvider != null) {
                        handleEnhancedSuggestion(editor, indicator);
                    } else {
                        handleBasicSuggestion(editor, indicator);
                    }
                } catch (Exception e) {
                    log.warn("Error generating suggestion, falling back to basic mode", e);
                    handleBasicSuggestion(editor, indicator);
                }
            }

            @Override
            public void onCancel() {
                // Clean up loading indicator if user cancels
                ApplicationManager.getApplication().invokeLater(() -> {
                    suggestionManager.disposeLoadingInlay();
                });
            }

            @Override
            public void onThrowable(@NotNull Throwable error) {
                // Clean up loading indicator on error
                ApplicationManager.getApplication().invokeLater(() -> {
                    suggestionManager.disposeLoadingInlay();
                });
                log.error("Suggestion generation failed", error);
            }
        }.queue();
    });
}
