    disposeLoadingInlay();
    disposeCurrentInlay();
    if (suggestionList.isEmpty()) {
        log.warn("No suggestions to display - suggestionList is empty");
        return;
    }
    this.suggestions = new ArrayList<>(suggestionList);
    this.currentSuggestionIndex = 0;
