Method: fr.baretto.ollamassist.chat.service.OllamaService#initAssistant
Signature: private Assistant initAssistant()
Body: {
    ClassLoader originalClassLoader = Thread.currentThread().getContextClassLoader();
    try {
        Thread.currentThread().setContextClassLoader(OllamaService.class.getClassLoader());
        documentIndexingPipeline.processSingleDocument(Document.from("empty doc"));
        OllamaStreamingChatModel.OllamaStreamingChatModelBuilder builder = OllamaStreamingChatModel.builder().temperature(0.7).topK(50).topP(0.85).baseUrl(OllamAssistSettings.getInstance().getChatOllamaUrl()).modelName(OllamAssistSettings.getInstance().getChatModelName()).timeout(OllamAssistSettings.getInstance().getTimeoutDuration());
        // Add authentication if configured (Basic or Bearer, resolved centrally)
        Map<String, String> authHeaders = AuthenticationHelper.authHeaders();
        if (!authHeaders.isEmpty()) {
            builder.customHeaders(authHeaders);
        }
        OllamaStreamingChatModel model = builder.build();
        var aiServicesBuilder = AiServices.builder(Assistant.class).streamingChatModel(model).chatMemory(chatMemory);
        // Only add tools if enabled in settings
        if (ActionsSettings.getInstance().isToolsEnabled()) {
            log.info("Tools are enabled - adding FileCreator tool");
            aiServicesBuilder.tools(new FileCreator(project));
        } else {
            log.info("Tools are disabled in settings");
        }
        return aiServicesBuilder.contentRetriever(new ContextRetriever(new HybridRetriever(embeddingStore, DocumentIngestFactory.createEmbeddingModel()), project)).build();
    } finally {
        Thread.currentThread().setContextClassLoader(originalClassLoader);
    }
}
