Method: fr.baretto.ollamassist.chat.ui.ChatThread#handleDetectedToolCall
Signature: private void handleDetectedToolCall(DetectedToolCall detectedCall)
Body: {
    if ("CreateFile".equals(detectedCall.getToolName())) {
        String path = detectedCall.getArguments().get("path");
        String content = detectedCall.getArguments().get("content");
        if (path != null && content != null) {
            log.info("Requesting approval for detected CreateFile call: {}", path);
            // Request user approval with warning indicator
            java.util.concurrent.CompletableFuture<FileApprovalNotifier.ApprovalDecision> approvalFuture = new java.util.concurrent.CompletableFuture<>();
            FileApprovalNotifier.ApprovalRequest request = FileApprovalNotifier.ApprovalRequest.builder().title("⚠️ Tool Call Detected (via text parsing)").filePath(path).content(content).responseFuture(approvalFuture).build();
            contextRef.project().getMessageBus().syncPublisher(FileApprovalNotifier.TOPIC).requestApproval(request);
            // Wait for approval
            ApplicationManager.getApplication().executeOnPooledThread(() -> {
                try {
                    FileApprovalNotifier.ApprovalDecision decision = approvalFuture.get(5, java.util.concurrent.TimeUnit.MINUTES);
                    if (decision.approved()) {
                        log.info("User approved detected tool call");
                        FileCreator fileCreator = new FileCreator(contextRef.project());
                        String result = fileCreator.createFile(path, content);
                        log.info("File creation result: {}", result);
                    } else {
                        log.info("User rejected detected tool call");
                    }
                    // Stop streaming
                    contextRef.project().getMessageBus().syncPublisher(StopStreamingNotifier.TOPIC).stopStreaming();
                } catch (Exception e) {
                    log.error("Error handling detected tool call", e);
                    Thread.currentThread().interrupt();
                }
            });
        }
    }
}
