Method: fr.baretto.ollamassist.completion.LightModelService#handleBasicSuggestion
Doc: * Handles basic suggestion generation (original implementation).
Signature: private void handleBasicSuggestion(Editor editor, ProgressIndicator indicator)
Body: {
    Document document = editor.getDocument();
    SelectionModel selectionModel = editor.getSelectionModel();
    String context;
    int caretOffset = editor.getCaretModel().getOffset();
    if (selectionModel.hasSelection()) {
        context = selectionModel.getSelectedText();
    } else {
        int startOffset = Math.max(0, caretOffset - 200);
        int endOffset = Math.min(document.getTextLength(), caretOffset);
        context = document.getText().substring(startOffset, endOffset);
    }
    try {
        indicator.setText("Generating basic suggestion...");
        String lineStartContent = getLineStartContent(editor).trim();
        String rawSuggestion = LightModelAssistant.get().completeBasic(context, getFileExtension(editor));
        String suggestion = extractCode(rawSuggestion, lineStartContent);
        ApplicationManager.getApplication().invokeLater(() -> {
            if (!indicator.isCanceled()) {
                suggestionManager.showSuggestion(editor, editor.getCaretModel().getOffset(), suggestion);
                attachKeyListener(editor, editor.getCaretModel().getOffset());
            }
        });
    } catch (Exception e) {
        log.error("Basic suggestion generation failed", e);
        // Even basic suggestion failed - show error or do nothing
    }
}
Method: fr.baretto.ollamassist.completion.InlineCompletionAction#actionPerformed
Signature: public void actionPerformed(@NotNull AnActionEvent e)
Body: {
    log.debug("InlineCompletionAction.actionPerformed() called");
    if (!isCodeCompletionEnabled()) {
        log.debug("Inline code completion is disabled in settings");
        return;
    }
    Project project = e.getProject();
    if (project == null) {
        log.debug("No project found");
        return;
    }
    Editor editor = getActiveEditor();
    if (editor == null) {
        log.debug("No active editor found");
        return;
    }
    log.debug("Found editor: {}", editor.getClass().getSimpleName());
    // Initialize enhanced completion service for this project if not already done
    if (enhancedCompletionService == null) {
        EnhancedContextProvider contextProvider = new EnhancedContextProvider(project);
        enhancedCompletionService = new EnhancedCompletionService(multiSuggestionManager, contextProvider);
    }
    // Attach the navigation key listener once per editor, not once per request.
    if (editor.getUserData(KEY_LISTENER_ATTACHED) == null) {
        editor.getContentComponent().addKeyListener(new EnhancedSuggestionKeyListener(multiSuggestionManager, editor));
        editor.putUserData(KEY_LISTENER_ATTACHED, Boolean.TRUE);
    }
    // Request completion with all optimizations
    log.debug("About to call enhancedCompletionService.requestCompletion()");
    enhancedCompletionService.requestCompletion(editor);
    log.debug("enhancedCompletionService.requestCompletion() called successfully");
}
Method: fr.baretto.ollamassist.completion.LightModelService#handleEnhancedSuggestion
Doc: * Handles suggestion generation with enhanced context (RAG + project analysis).
Signature: private void handleEnhancedSuggestion(Editor editor, ProgressIndicator indicator)
Body: {
    indicator.setText("Building enhanced context...");
    // Build completion context asynchronously
    CompletableFuture<CompletionContext> contextFuture = contextProvider.buildCompletionContextAsync(editor);
    contextFuture.thenAccept(completionContext -> {
        if (indicator.isCanceled()) {
            return;
        }
        indicator.setText("Generating AI suggestion...");
        try {
            String lineStartContent = getLineStartContent(editor).trim();
            // Use enhanced completion with rich context
            String rawSuggestion = LightModelAssistant.get().complete(completionContext.getImmediateContext(), completionContext.getFileExtension(), completionContext.getProjectContext(), completionContext.getSimilarPatterns());
            String suggestion = extractCode(rawSuggestion, lineStartContent);
            ApplicationManager.getApplication().invokeLater(() -> {
                if (!indicator.isCanceled()) {
                    suggestionManager.showSuggestion(editor, editor.getCaretModel().getOffset(), suggestion);
                    attachKeyListener(editor, editor.getCaretModel().getOffset());
                }
            });
        } catch (Exception e) {
            log.warn("Enhanced suggestion failed, trying basic fallback", e);
            handleBasicSuggestion(editor, indicator);
        }
    }).exceptionally(throwable -> {
        log.warn("Context building failed, using basic suggestion", throwable);
        handleBasicSuggestion(editor, indicator);
        return null;
    });
}
Method: fr.baretto.ollamassist.completion.EnhancedCompletionService#generateBasicSuggestion
Doc: * Fallback to basic suggestion generation.
Signature: private void generateBasicSuggestion(@NotNull Editor editor, @NotNull ProgressIndicator indicator)
Body: {
    indicator.setText("Generating basic suggestion...");
    String basicContext = getBasicContext(editor);
    String fileExtension = getFileExtension(editor);
    CompletableFuture<String> basicCompletionFuture = OptimizedLightModelAssistant.completeBasicAsync(basicContext, fileExtension);
    basicCompletionFuture.thenAccept(rawSuggestion -> {
        if (indicator.isCanceled()) {
            return;
        }
        try {
            String processedSuggestion = processSuggestion(rawSuggestion, editor);
            ApplicationManager.getApplication().invokeLater(() -> {
                if (!indicator.isCanceled()) {
                    int caretOffset = ApplicationManager.getApplication().runReadAction((Computable<Integer>) () -> editor.getCaretModel().getOffset());
                    suggestionManager.showSuggestion(editor, caretOffset, processedSuggestion);
                    attachActionHandler(editor);
                }
            });
        } catch (Exception e) {
            log.error("Basic suggestion processing failed", e);
            ApplicationManager.getApplication().invokeLater(() -> {
                suggestionManager.disposeLoadingInlay();
            });
        }
    }).exceptionally(throwable -> {
        log.error("Basic suggestion generation failed", throwable);
        ApplicationManager.getApplication().invokeLater(() -> {
            suggestionManager.disposeLoadingInlay();
        });
        return null;
    });
}
