Method: fr.baretto.ollamassist.prerequiste.PrerequisitesPanel#checkPrerequisitesAsync
Signature: private void checkPrerequisitesAsync()
Body: {
    OllamAssistSettings settings = OllamAssistSettings.getInstance();
    // Check if model names are configured
    boolean chatModelConfigured = isModelNameValid(settings.getChatModelName());
    boolean autocompleteModelConfigured = isModelNameValid(settings.getCompletionModelName());
    boolean embeddingModelConfigured = isModelNameValid(settings.getEmbeddingModelName());
    CompletableFuture<Boolean> ollamaRunningFuture = prerequisiteService.isOllamaRunningAsync(settings.getChatOllamaUrl());
    CompletableFuture<Boolean> chatModelFuture = chatModelConfigured ? prerequisiteService.isChatModelAvailableAsync(settings.getChatOllamaUrl(), settings.getChatModelName()) : CompletableFuture.completedFuture(false);
    CompletableFuture<Boolean> autocompleteModelFuture = autocompleteModelConfigured ? prerequisiteService.isAutocompleteModelAvailableAsync(settings.getCompletionOllamaUrl(), settings.getCompletionModelName()) : CompletableFuture.completedFuture(false);
    CompletableFuture<EmbeddingModelCheckResult> embeddingModelFuture = embeddingModelConfigured ? prerequisiteService.checkEmbeddingModelAsync(settings.getEmbeddingOllamaUrl(), settings.getEmbeddingModelName()) : CompletableFuture.completedFuture(EmbeddingModelCheckResult.notAvailable());
    CompletableFuture.allOf(ollamaRunningFuture, chatModelFuture, autocompleteModelFuture, embeddingModelFuture).thenAccept(v -> {
        boolean ollamaReady = ollamaRunningFuture.join();
        boolean chatModelReady = chatModelConfigured && chatModelFuture.join();
        boolean autocompleteModelReady = autocompleteModelConfigured && autocompleteModelFuture.join();
        EmbeddingModelCheckResult embeddingResult = embeddingModelFuture.join();
        boolean embeddingModelReady = embeddingModelConfigured && embeddingResult.isUsable();
        ApplicationManager.getApplication().invokeLater(() -> updateUI(ollamaReady, chatModelReady, autocompleteModelReady, embeddingResult, chatModelConfigured, autocompleteModelConfigured, embeddingModelConfigured));
        if (ollamaReady && chatModelReady && autocompleteModelReady && embeddingModelReady) {
            project.getService(OllamaService.class).init();
            LightModelAssistant.get();
            ApplicationManager.getApplication().getMessageBus().syncPublisher(ModelAvailableNotifier.TOPIC).onModelAvailable();
        }
    });
}

