Method: fr.baretto.ollamassist.chat.rag.DocumentIngestFactory#createOllamaEmbeddingModel
Doc: * Creates an Ollama embedding model with configured settings.
     *
     * @param modelName Name of the Ollama model to use
     * @return Configured OllamaEmbeddingModel
Signature: private static OllamaEmbeddingModel createOllamaEmbeddingModel(String modelName)
Body: {
    OllamaEmbeddingModel.OllamaEmbeddingModelBuilder builder = new OllamaEmbeddingModel.OllamaEmbeddingModelBuilder();
    builder.baseUrl(OllamAssistSettings.getInstance().getEmbeddingOllamaUrl()).modelName(modelName).timeout(OllamAssistSettings.getInstance().getTimeoutDuration());
    // Add authentication if configured (Basic or Bearer, resolved centrally)
    Map<String, String> authHeaders = AuthenticationHelper.authHeaders();
    if (!authHeaders.isEmpty()) {
        builder.customHeaders(authHeaders);
    }
    return builder.build();
}
